-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — "Clearly trivial" misstatement threshold
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does "clearly trivial" mean when applied to misstatements?', '["The misstatement is inconsequential whether taken individually or in the aggregate", "The misstatement falls below the planning materiality threshold", "The misstatement was caused by an unintentional error rather than fraud", "The misstatement affects only disclosure items rather than account balances"]'::jsonb, 0, 'AU-C 450.A2 defines clearly trivial as a threshold below which misstatements are inconsequential, whether individually or in the aggregate. This is not the same as immaterial—clearly trivial is a lower bar. Unlike choice B, clearly trivial is distinct from planning materiality and is set at an amount well below materiality.', 'easy', 1),

-- Q2: medium / L3 — Iron curtain approach for evaluating balance sheet misstatement effect
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgefield Electronics, the auditor identifies $40,000 in uncorrected prior-year misstatements that remain on the balance sheet, plus $12,000 in new current-year misstatements. Materiality is $50,000. Under the iron curtain approach, the auditor should evaluate the aggregate misstatement as:', '["$12,000 because only current-year misstatements affect this year''s opinion", "$52,000 because the iron curtain approach considers the total accumulated effect on the balance sheet", "$40,000 because prior-year misstatements take priority in the evaluation", "$28,000 because the iron curtain approach nets prior-year against current-year misstatements"]'::jsonb, 1, 'AU-C 450.A16 describes the iron curtain approach as evaluating the total amount of misstatement remaining in the ending balance sheet, regardless of when the misstatement originated. The total is $40,000 + $12,000 = $52,000, which exceeds the $50,000 materiality. Unlike choice A (the rollover approach), the iron curtain method does not limit evaluation to current-year items only.', 'medium', 3),

-- Q3: medium / L3 — Evaluating whether interim control deficiency persists to year-end
(1, 'Misstatements and Control Deficiencies', 'During interim testing at Cascade Financial Group, the auditor identified a significant deficiency in the bank reconciliation process. By year-end, management implemented new reconciliation procedures. Under AU-C 265, the auditor''s evaluation of the deficiency should be based on:', '["The severity of the deficiency at the time it was originally identified during interim testing", "Whether the deficiency was communicated to those charged with governance during interim fieldwork", "Whether the remediated control operated effectively for a sufficient period before year-end", "Whether management provided a written representation confirming the deficiency was corrected"]'::jsonb, 2, 'AU-C 265.A14 requires the auditor to evaluate control deficiencies as of the report date. When management remediates a deficiency, the auditor must assess whether the new control operated effectively for a sufficient period. Unlike choice A, the severity at interim is not the final basis—the auditor must consider remediation before concluding on the year-end classification.', 'medium', 3),

-- Q4: hard / L4 — Evaluating interaction of entity-level and process-level deficiencies
(1, 'Misstatements and Control Deficiencies', 'Westbrook Industries has a weak control environment—the CFO overrides reconciliation approvals monthly and no independent audit committee exists. The auditor also finds that accounts payable lacks three-way matching for purchases under $5,000, affecting $180,000 in annual transactions. Materiality is $200,000. Which analysis best reflects AU-C 265 guidance?', '["Each deficiency should be evaluated independently because they affect different financial statement assertions", "The process-level deficiency alone is immaterial and the entity-level weakness is a governance concern only, so neither rises to a material weakness", "Only the CFO override is a material weakness because entity-level deficiencies always supersede process-level deficiencies", "The entity-level weakness exacerbates the process-level deficiency because the compensating effect of management oversight is compromised, and combined they likely constitute a material weakness"]'::jsonb, 3, 'AU-C 265.A12 requires auditors to evaluate whether individual deficiencies combine to create a material weakness. Entity-level weaknesses like CFO override and lack of audit committee undermine compensating controls, amplifying process-level deficiencies. Unlike choice A, deficiencies cannot be evaluated in isolation when entity-level weaknesses compromise the control environment that other controls depend on.', 'hard', 4),

-- Q5: medium / L2 — Distinguishing deficiency in design from deficiency in operation
(1, 'Misstatements and Control Deficiencies', 'At Birchwood Manufacturing, the auditor finds that management designed a monthly inventory count procedure but the warehouse supervisor only performs the count quarterly. Under AU-C 265, this situation represents:', '["A deficiency in the operation of a control because the designed procedure exists but is not performed as intended", "A deficiency in the design of a control because the quarterly frequency is inadequate", "A material weakness because the inventory count is performed at insufficient intervals", "An insignificant deficiency because inventory counts are still being performed"]'::jsonb, 0, 'AU-C 265.07 distinguishes between design and operation deficiencies. A design deficiency exists when a control is missing or improperly designed. An operation deficiency occurs when a properly designed control does not operate as intended. Here, the monthly count is properly designed but executed quarterly, making it an operation deficiency. Choice B is incorrect because the design itself (monthly counts) is appropriate.', 'medium', 2),

-- Q6: medium / L3 — Qualitative factors making an immaterial misstatement significant
(1, 'Misstatements and Control Deficiencies', 'Pinnacle Consulting''s auditor discovers a $3,000 misstatement in executive bonus accruals. Materiality is $250,000. However, the misstatement resulted from the CEO manually adjusting the bonus calculation without documentation. The auditor should:', '["Classify the misstatement as clearly trivial since $3,000 is well below materiality", "Record the misstatement on the summary schedule but take no further action", "Reduce materiality to capture executive compensation misstatements", "Evaluate the qualitative significance of the misstatement because it may indicate management override of controls"]'::jsonb, 3, 'AU-C 450.A5 requires auditors to consider qualitative factors when evaluating misstatements, even those below materiality. A misstatement involving management override of controls—such as undocumented CEO adjustments—may signal fraud risk regardless of dollar amount. Unlike choice A, quantitative immateriality alone does not determine whether a misstatement requires further investigation.', 'medium', 3),

-- Q7: easy / L1 — Purpose of the summary of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the purpose of the summary of uncorrected misstatements the auditor accumulates during an audit?', '["To document all adjusting journal entries management has agreed to record", "To compile identified misstatements that management has not corrected for evaluation against materiality", "To provide a list of internal control recommendations for management", "To calculate the total audit adjustments for the financial statements"]'::jsonb, 1, 'AU-C 450.06 requires the auditor to accumulate all identified misstatements during the audit, other than those that are clearly trivial. This summary of uncorrected misstatements is used to evaluate their aggregate effect on the financial statements. Unlike choice A, the summary captures misstatements management chose NOT to correct, not adjusting entries already recorded.', 'easy', 1),

-- Q8: hard / L4 — Evaluating whether post-period control remediation affects current-year deficiency
(1, 'Misstatements and Control Deficiencies', 'Silverstone Corp. had a material weakness in revenue recognition reported in the prior year. Management hired additional staff and implemented automated controls on January 15, 2026. The auditor is evaluating the current-year financial statements ending December 31, 2025. The auditor should conclude that:', '["The material weakness no longer exists because management has taken corrective action", "The remediation eliminates the material weakness for both current and prior-year reporting", "The material weakness still existed as of December 31, 2025 because the remediation occurred after the balance sheet date and was not in place during the audit period", "The material weakness can be downgraded to a significant deficiency because management demonstrated intent to remediate"]'::jsonb, 2, 'AU-C 265.A14 requires evaluating control deficiencies as of the financial statement date. Since remediation occurred January 15, 2026—after the December 31, 2025 balance sheet date—the material weakness existed throughout the audit period. Unlike choice A, post-period remediation does not retroactively eliminate a deficiency that was present during the period under audit.', 'hard', 4),

-- Q9: medium / L2 — Written representation for uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'After completing fieldwork at Greenfield Distributors, the auditor presents management with a summary of $18,000 in uncorrected misstatements, all below the $300,000 materiality threshold. Management declines to correct them. Under AU-C 450, what must the auditor obtain from management?', '["A revised set of financial statements reflecting the uncorrected misstatements as disclosed items", "An oral acknowledgment during the closing conference that the misstatements are immaterial", "A formal engagement letter amendment addressing the uncorrected items", "A written representation that management believes the uncorrected misstatements are immaterial, both individually and in the aggregate"]'::jsonb, 3, 'AU-C 450.14 requires the auditor to obtain a written representation from management that it believes the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. Unlike choice B, an oral acknowledgment is insufficient—the representation must be in writing as part of the management representation letter.', 'medium', 2),

-- Q10: easy / L1 — Definition of a control deviation
(1, 'Misstatements and Control Deficiencies', 'In the context of evaluating internal controls, what is a control deviation?', '["A misstatement in the financial statements caused by an error in an accounting estimate", "An instance in which a prescribed control procedure was not performed or was performed incorrectly", "A management decision to override an automated control for business reasons", "A difference between the auditor''s expectation and the recorded amount in a substantive test"]'::jsonb, 1, 'AU-C 530.A20 describes a control deviation as an instance where a prescribed control procedure was not applied or was applied incorrectly. Deviations are identified during tests of controls and may indicate a control deficiency. Unlike choice D, which describes a difference from substantive testing, a deviation relates specifically to the operation of a control.', 'easy', 1),

-- Q11: easy / L1 — Communication of deficiencies below significant deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, how must the auditor communicate control deficiencies that are not significant deficiencies or material weaknesses?', '["The auditor is not required to communicate deficiencies below the significant deficiency threshold but may choose to do so", "The auditor must issue a formal written report on all control deficiencies regardless of severity", "The auditor must communicate all deficiencies verbally to the audit committee", "The auditor must include all control deficiencies in the management representation letter"]'::jsonb, 0, 'AU-C 265.12 states that the auditor is not required to communicate control deficiencies that are less severe than a significant deficiency; however, the auditor may choose to communicate them to management. Unlike choice B, there is no requirement for a formal written report on every control deficiency—only significant deficiencies and material weaknesses require written communication.', 'easy', 1),

-- Q12: medium / L2 — Pattern of one-directional misstatements suggesting bias
(1, 'Misstatements and Control Deficiencies', 'During the audit of Atlas Retail Corp., the auditor notices that all eight uncorrected misstatements, totaling $45,000 against $500,000 materiality, uniformly increase reported net income. Under AU-C 450, the auditor should evaluate whether this pattern indicates:', '["Random estimation errors that require no additional consideration", "Intentional misstatement requiring immediate withdrawal from the engagement", "Possible management bias in the preparation of the financial statements", "A significant deficiency that must be communicated to those charged with governance"]'::jsonb, 2, 'AU-C 450.A10 requires the auditor to consider whether uncorrected misstatements share characteristics suggesting management bias—such as consistently overstating income. A one-directional pattern warrants further evaluation for fraud risk. Unlike choice A, a uniform direction across all misstatements is unlikely to be random and requires the application of professional skepticism.', 'medium', 2),

-- Q13: medium / L2 — Timeline for written communication of significant deficiencies
(1, 'Misstatements and Control Deficiencies', 'Lakewood Healthcare''s auditor identifies several significant deficiencies during the December 2025 audit. The audit report is dated March 15, 2026. Under AU-C 265, when must the auditor communicate these deficiencies in writing to those charged with governance?', '["Within 30 days of identifying the deficiencies during fieldwork", "Concurrently with the issuance of the auditor''s report on the financial statements", "Before the entity files its annual report with regulators", "No later than 60 days following the release of the auditor''s report"]'::jsonb, 3, 'AU-C 265.13 requires written communication of significant deficiencies and material weaknesses no later than 60 days following the release of the auditor''s report. This allows the auditor time to finalize the evaluation after the report date. Unlike choice A, there is no 30-day-from-identification deadline—the 60-day clock starts from the report release date.', 'medium', 2),

-- Q14: medium / L3 — Prior-year significant deficiency not remediated must be re-communicated
(1, 'Misstatements and Control Deficiencies', 'During the prior-year audit of Redstone Construction, the auditor communicated a significant deficiency in job-cost allocation. During the current-year audit, the auditor determines the same deficiency persists with no remediation by management. Under AU-C 265, the auditor should:', '["Reference the prior-year communication and note that no further action is required since the deficiency was previously reported", "Include the deficiency only in the management letter rather than the written communication", "Issue only an oral communication since the matter was already communicated in writing", "Communicate the significant deficiency again in writing because it continues to exist as of the current reporting date"]'::jsonb, 3, 'AU-C 265.A18 states that if a previously communicated significant deficiency remains unremediated, the auditor should communicate it again in the current year. Each year''s communication stands independently. Unlike choice A, a prior-year communication does not satisfy the current-year requirement—the deficiency must be reported each year it exists.', 'medium', 3),

-- Q15: easy / L1 — Tolerable misstatement in audit sampling
(1, 'Misstatements and Control Deficiencies', 'What is tolerable misstatement as used in audit sampling under AU-C 530?', '["The maximum misstatement in a population that the auditor is willing to accept and still conclude the audit objective is achieved", "The total dollar amount of all known misstatements found in a sample", "The amount by which the auditor reduces materiality for undetected misstatements", "The misstatement level at which the auditor must withdraw from the engagement"]'::jsonb, 0, 'AU-C 530.05 defines tolerable misstatement as the application of performance materiality to a particular sampling procedure—the maximum misstatement the auditor can accept in a population and still conclude the objective is achieved. Unlike choice C, which describes performance materiality at the overall financial statement level, tolerable misstatement applies specifically to individual account populations tested through sampling.', 'easy', 1),

-- Q16: easy / L1 — Recipients of written material weakness communication
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, to whom must the auditor communicate material weaknesses in writing?', '["The entity''s external legal counsel and regulatory authorities", "Those charged with governance and management", "Only the chief executive officer of the entity", "All employees involved in the financial reporting process"]'::jsonb, 1, 'AU-C 265.11 requires the auditor to communicate in writing to those charged with governance all significant deficiencies and material weaknesses identified during the audit. Management also receives written communication. Unlike choice A, there is no requirement to communicate directly to external legal counsel or regulators—the obligation runs to governance and management.', 'easy', 1),

-- Q17: easy / L1 — Fraud versus error distinction
(1, 'Misstatements and Control Deficiencies', 'What distinguishes a misstatement arising from fraud from a misstatement arising from error?', '["The dollar amount of the misstatement exceeds materiality only in fraud cases", "Fraud misstatements always involve senior management whereas errors involve staff-level employees", "A misstatement from fraud involves an intentional act whereas a misstatement from error is unintentional", "Error misstatements affect only balance sheet accounts whereas fraud misstatements affect income"]'::jsonb, 2, 'AU-C 240.04 defines fraud as an intentional act by one or more individuals resulting in a misstatement of the financial statements, whereas errors are unintentional mistakes. The key distinction is intent, not the amount or the person involved. Unlike choice B, fraud can be committed by employees at any level, and errors can occur at any level as well.', 'easy', 1),

-- Q18: medium / L2 — Rollover approach for evaluating misstatement accumulation
(1, 'Misstatements and Control Deficiencies', 'At Timberline Logistics, the auditor identifies $22,000 in current-year misstatements. Prior-year uncorrected misstatements totaling $35,000 remain on the balance sheet. Materiality is $50,000. Under the rollover approach, the amount evaluated against current-year materiality is:', '["$22,000 because the rollover approach focuses only on misstatements originating in the current year", "$57,000 because both current and prior-year misstatements are combined under the rollover approach", "$35,000 because prior-year misstatements take priority over current-year misstatements", "$13,000 because the rollover approach nets the difference between current and prior-year amounts"]'::jsonb, 0, 'AU-C 450.A16 describes the rollover approach as evaluating only the misstatements arising in the current period, without regard to carryover effects of prior-year misstatements on the current-period balance sheet. The $22,000 in current-year misstatements is compared to the $50,000 materiality. Unlike choice B (the iron curtain approach), the rollover method does not aggregate prior-period amounts with current-period amounts.', 'medium', 2),

-- Q19: medium / L2 — Documentation of clearly trivial threshold during planning
(1, 'Misstatements and Control Deficiencies', 'During the planning phase of the audit of Northwind Technologies, the engagement partner sets the clearly trivial threshold at $2,500. Under AU-C 450, the auditor''s documentation regarding this threshold should:', '["Include the amount designated as clearly trivial and the basis for that determination in the audit documentation", "Communicate the threshold to management for their approval before finalizing it", "Submit the threshold to those charged with governance for formal ratification", "Record the threshold only if misstatements exceeding it are subsequently identified during fieldwork"]'::jsonb, 0, 'AU-C 450.A2 requires the auditor to determine an amount below which misstatements are clearly trivial. This threshold should be documented in the audit file with the basis for its determination as a planning decision. Unlike choice D, the threshold is established during planning and documented regardless of whether misstatements are later found—it is not a reactive measure.', 'medium', 2),

-- Q20: hard / L4 — Integrated audit: reconciling conflicting deficiency severity between FS and ICFR
(1, 'Misstatements and Control Deficiencies', 'In an integrated audit of Meridian Financial Corp., the engagement team classifies a payroll processing deficiency as a significant deficiency based on the financial statement audit. However, the ICFR evaluation reveals that the same control processes 85% of total compensation expense, and a breakdown could result in a material misstatement. Under PCAOB AS 2201, the engagement team should:', '["Classify the deficiency as a material weakness because the ICFR evaluation indicates a reasonable possibility of material misstatement, and the more severe classification governs", "Maintain the significant deficiency classification from the financial statement audit because it was determined first chronologically", "Average the two assessments and classify the deficiency at an intermediate severity level", "Report the significant deficiency in the financial statement audit report and the material weakness separately in the ICFR report"]'::jsonb, 0, 'PCAOB AS 2201.62 requires that in an integrated audit, the auditor use the most severe classification when the financial statement audit and ICFR evaluation yield different severity levels for the same deficiency. Since the ICFR evaluation indicates a reasonable possibility of material misstatement, it governs. Unlike choice D, the auditor cannot report different severity classifications for the same deficiency across the two reports.', 'hard', 4),

-- Q21: hard / L4 — Aggregate uncorrected misstatements plus projected misstatements exceeding materiality
(1, 'Misstatements and Control Deficiencies', 'At year-end, Crestline Manufacturing has $185,000 in accumulated uncorrected misstatements, all affecting accounts receivable. Overall materiality is $200,000 and performance materiality is $150,000. The auditor has also identified a $30,000 likely misstatement from sampling. The auditor should conclude that:', '["No modification is needed because the $185,000 total remains below the $200,000 overall materiality threshold", "The aggregate of uncorrected misstatements plus the likely misstatement totals $215,000, exceeding overall materiality and requiring either correction or a modified opinion", "Only the likely misstatement of $30,000 should be evaluated because projected amounts supersede known amounts", "Performance materiality of $150,000 is the relevant threshold and since it was already exceeded, no further evaluation is necessary"]'::jsonb, 1, 'AU-C 450.11 requires the auditor to evaluate the aggregate effect of uncorrected misstatements, including known and likely misstatements. The total is $185,000 + $30,000 = $215,000, which exceeds overall materiality of $200,000. The auditor must request correction or modify the opinion. Unlike choice A, likely misstatements from sampling cannot be ignored when aggregating uncorrected misstatements.', 'hard', 4),

-- Q22: hard / L4 — Year-end entries structured below clearly trivial threshold indicating fraud risk
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Industries, the auditor observes that management made 14 discretionary adjusting entries in the final week of the fiscal year, all increasing revenue by amounts just below the clearly trivial threshold. Combined, these entries total $95,000 against materiality of $100,000. Under AU-C 240 and AU-C 450, the auditor should:', '["Accept each individual entry as clearly trivial since none exceeds the threshold independently", "Treat the entries as routine period-end adjustments requiring no further consideration", "Evaluate whether the pattern of entries just below the clearly trivial threshold indicates intentional manipulation and potential fraud risk requiring expanded procedures", "Require management to reverse all entries because discretionary adjustments at year-end are presumed fraudulent"]'::jsonb, 2, 'AU-C 240.32 and AU-C 450.A5 require the auditor to exercise professional skepticism when evaluating misstatements that, while individually small, form a pattern suggesting possible management bias or fraud. Entries deliberately structured below detection thresholds indicate potential intentional manipulation. Unlike choice A, the clearly trivial threshold applies to individual items and does not override the obligation to evaluate aggregate patterns.', 'hard', 4),

-- Q23: medium / L3 — Post-year-end remediation does not change current-year classification
(1, 'Misstatements and Control Deficiencies', 'Hilltop Energy reported a material weakness in its December 31, 2025 audit related to inadequate segregation of duties in accounts payable. On February 10, 2026, management hired additional staff and redesigned the workflow. The auditor''s report is dated March 1, 2026. Under AU-C 265, the auditor should:', '["Remove the material weakness from the communication because remediation occurred before the report date", "Downgrade the classification to a significant deficiency since management demonstrated corrective intent", "Note the remediation as a subsequent event that eliminates the need for communication", "Communicate the material weakness as of December 31, 2025 and may separately note that management has taken subsequent remedial action"]'::jsonb, 3, 'AU-C 265.A14 requires deficiency evaluation as of the financial statement date. Since the weakness existed throughout the year ended December 31, 2025, it must be reported as a material weakness for that period. The auditor may note subsequent remediation but cannot reclassify. Unlike choice A, remediation after year-end does not retroactively change the current-year classification.', 'medium', 3),

-- Q24: medium / L3 — Compensating control partial mitigation of access control weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Beacon Software, the auditor identifies that the system administrator has unrestricted access to modify both production code and financial databases. Management argues that a quarterly access log review by the IT director serves as a compensating control. The auditor should evaluate whether:', '["The compensating control fully eliminates the deficiency since management reviews occur quarterly", "The quarterly review frequency is automatically sufficient because any detective control mitigates a preventive control weakness", "The compensating control operates at a sufficient level to reduce the severity of the deficiency, considering the frequency and thoroughness of the review relative to the risk", "No compensating control can ever mitigate an access control deficiency under auditing standards"]'::jsonb, 2, 'AU-C 265.A8 requires the auditor to consider compensating controls when evaluating deficiency severity. A compensating control may reduce severity only if it operates at a sufficient level—considering frequency, timeliness, and thoroughness—to address the underlying risk. Unlike choice A, a quarterly review may not fully compensate for continuous unrestricted access if the review frequency is insufficient relative to the risk.', 'medium', 3),

-- Q25: easy / L2 — Responsibility for correcting identified misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cedar Valley Foods, the auditor identifies $28,000 in inventory pricing errors. Under AU-C 450, the responsibility for correcting these misstatements belongs to:', '["Management of the entity", "The engagement partner on the audit", "Those charged with governance exclusively", "The entity''s external legal counsel"]'::jsonb, 0, 'AU-C 450.08 requires the auditor to communicate identified misstatements to the appropriate level of management on a timely basis. Management holds the responsibility for preparing and fairly presenting the financial statements, including correcting misstatements. Unlike choice B, the auditor''s role is to identify and communicate misstatements, not to correct them—that responsibility rests with management.', 'easy', 2),

-- Q26: medium / L3 — Pervasive control environment weakness cascading to multiple accounts
(1, 'Misstatements and Control Deficiencies', 'Stonebridge Corp. lacks a formal code of ethics, has no whistleblower hotline, and the board of directors does not meet regularly to discuss financial reporting. During the audit, the auditor finds isolated misstatements in revenue, inventory, and accounts payable. Under AU-C 265, the auditor should evaluate these control environment weaknesses as:', '["Separate deficiencies to be communicated individually for each account affected", "A pervasive entity-level weakness that may constitute a material weakness because it undermines the foundation upon which other controls depend", "Governance recommendations that fall outside the scope of the auditor''s required communications", "Significant deficiencies only because no single misstatement was individually material"]'::jsonb, 1, 'AU-C 265.A11 recognizes that entity-level control environment weaknesses are pervasive because they affect the reliability of all financial reporting controls. Lack of ethical tone, absent governance oversight, and missing reporting mechanisms undermine the entire control foundation. Unlike choice A, these are not isolated process-level deficiencies—they represent a systemic weakness affecting multiple areas simultaneously.', 'medium', 3),

-- Q27: medium / L2 — Rate of control failure and magnitude in severity evaluation
(1, 'Misstatements and Control Deficiencies', 'The auditor of Maple Grove Hospital tested 40 purchase order approvals and found 3 instances where approval was not obtained before payment. Each unapproved payment was under $500 and materiality is $150,000. Under AU-C 265, the auditor should consider:', '["Only the dollar amount of the three exceptions when evaluating deficiency severity", "Whether the three unapproved payments constitute fraud requiring immediate reporting to regulators", "The percentage of the total population that was tested rather than the sample results", "Both the rate of control failure in the sample and the potential magnitude of errors the control is designed to prevent when evaluating severity"]'::jsonb, 3, 'AU-C 265.A9 requires the auditor to consider both the likelihood (rate of control failure) and the magnitude (potential financial impact) when evaluating severity. A 7.5% failure rate may indicate a systemic issue even if individual amounts are small. Unlike choice A, the dollar amount of observed exceptions alone is insufficient—the auditor must also assess what could go wrong given the control failure rate across the full population.', 'medium', 2),

-- Q28: medium / L2 — Key personnel turnover as a control environment deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Foxworth Electronics, the auditor learns that three different controllers served during the fiscal year, each departing within four months. Several month-end reconciliations were incomplete during transitions. Under AU-C 265, this situation is most relevant to evaluating:', '["Whether the staffing instability represents a control environment deficiency that increases the risk of material misstatement", "Whether the entity should change its accounting software to reduce reliance on individual personnel", "Whether the auditor should increase fee estimates due to additional audit work required", "Whether the prior auditor''s workpapers should be re-examined for consistency"]'::jsonb, 0, 'AU-C 265.A11 identifies staffing issues as a factor in evaluating entity-level control deficiencies. High turnover in key accounting positions compromises the control environment and may result in incomplete procedures, increasing the risk of material misstatement. Unlike choice B, the auditor''s evaluation focuses on the control environment impact of staffing instability, not on recommending specific operational changes.', 'medium', 2),

-- Q29: hard / L3 — Multi-period misstatement accumulation requiring restatement evaluation
(1, 'Misstatements and Control Deficiencies', 'The auditor of Pacific Coast Enterprises discovers that a $60,000 revenue recognition error originated three years ago and has compounded through retained earnings. Current-year materiality is $100,000, but the cumulative balance sheet effect is $180,000. Under AU-C 450 and AU-C 560, the auditor must evaluate:', '["Only the current-year impact because prior-year financial statements have already been issued with unmodified opinions", "Whether the $60,000 annual amount is material to any individual prior-period financial statement before concluding on the current-year effect", "Whether the cumulative $180,000 effect is material to the current-year financial statements under the iron curtain approach and whether prior-period financial statements may require restatement", "Only whether management agrees to correct the error prospectively starting in the current year"]'::jsonb, 2, 'AU-C 450.A16 and AU-C 560 require the auditor to evaluate the cumulative balance sheet effect (iron curtain) of misstatements, including those originating in prior periods. The $180,000 exceeds current-year materiality. The auditor must also consider whether prior-period statements were materially misstated, potentially requiring restatement. Unlike choice A, previously issued opinions do not immunize prior-period misstatements from reconsideration.', 'hard', 3),

-- Q30: easy / L1 — Definition of pervasive effect on financial statements
(1, 'Misstatements and Control Deficiencies', 'In auditing standards, what characterizes a misstatement as having a pervasive effect on the financial statements?', '["The misstatement exceeds overall materiality for the audit", "The misstatement is not confined to specific elements but affects many accounts, represents a substantial proportion of the financial statements, or undermines disclosure credibility", "The misstatement was caused by fraud rather than error", "The misstatement was identified during substantive testing rather than tests of controls"]'::jsonb, 1, 'AU-C 705.05 defines a pervasive effect as one that is not confined to specific elements, accounts, or items and could represent a substantial proportion of the financial statements or fundamentally affect users'' understanding of the disclosures. Unlike choice A, a misstatement need not exceed materiality to be pervasive—the concept addresses breadth of impact across the financial statements.', 'easy', 1)
;

COMMIT;
